// Campaign scoping for the Real Good AI donation widgets: the pure rules, kept apart from the
// elements so they can be unit-tested.

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * The campaign id from an attribute: null when there is none (a general, site-wide widget),
 * the lowercase UUID when valid. Anything else throws, because the id is interpolated into
 * query filters and a campaign page must never silently fall back to the site-wide feed.
 */
export function parseCampaignId(attr: string | null): string | null {
  if (attr === null || attr.trim() === '') return null;
  const id = attr.trim();
  if (!UUID.test(id)) throw new Error('Invalid campaign-id: expected a UUID.');
  return id.toLowerCase();
}

/**
 * The campaign slug from an attribute, or null. Slugs are lowercase letters, digits and hyphens
 * (what create-campaign accepts); anything else is ignored rather than sent to the server.
 */
export function parseCampaignSlug(attr: string | null): string | null {
  const slug = attr?.trim().toLowerCase() ?? '';
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) ? slug : null;
}

/** The `context` the donation form sends: the campaign slug, or nothing for a general donation. */
export function checkoutContextFor(slug: string | null): { campaignSlug: string } | undefined {
  return slug ? { campaignSlug: slug } : undefined;
}

/**
 * Realtime filters for a campaign: donations made directly to it, and ones rolled up into it
 * (two subscriptions, because a filter cannot express OR). No campaign: unfiltered.
 */
export function campaignRealtimeFilters(campaignId: string | null): string[] {
  return campaignId ? [`campaign_id=eq.${campaignId}`, `rollup_campaign_id=eq.${campaignId}`] : [];
}

/** PostgREST `or` filter for "direct or rolled-up" donations of a campaign. */
export function campaignOrFilter(campaignId: string): string {
  return `campaign_id.eq.${campaignId},rollup_campaign_id.eq.${campaignId}`;
}

/** Extra arguments of `leaderboard_rankings`; production always passes `p_campaign_id`, null for site-wide. */
export function leaderboardCampaignArgs(campaignId: string | null): { p_campaign_id: string | null } {
  return { p_campaign_id: campaignId };
}
